<?php
function lop_review_precision_confirmation(array $proposal): void {
    if(($proposal['bank']['source_balance_raw']??null)!==null&&$proposal['bank']['source_balance']===null)echo '<p class="dbt-info">Saldo sumber mentah: <strong>'.loe($proposal['bank']['source_balance_raw']).'</strong>. Saldo operasional mengikuti FIX yang disahkan.</p>';
    if(empty($proposal['journal_changes']))return;
    echo '<h3>Koreksi presisi jurnal yang ikut disahkan</h3><p>Nilai operasional dibulatkan ke dua desimal. Nominal sumber asli tetap tersimpan.</p><div class="dbt-table-scroll"><table class="dbt-table legacy-directory-table lop-precision-table"><thead><tr><th>Tanggal sumber</th><th>Arah</th><th>Nominal sumber (Rp)</th><th>Nominal disahkan (Rp)</th></tr></thead><tbody>';
    foreach($proposal['journal_changes'] as $change)echo '<tr><td data-label="Tanggal sumber">'.loe(substr($change['date']??'',0,10)).'</td><td data-label="Arah">'.($change['column']==='MASUK'?'Masuk':'Keluar').'</td><td data-label="Nominal sumber (Rp)">'.loe($change['original']).'</td><td data-label="Nominal disahkan (Rp)">'.loe($change['amount']).'</td></tr>';
    echo '</tbody></table></div>';
}
/** Server-rendered review panels: the same versioned draft is used without JavaScript. */
function lop_review_people(array $plan,array $cfg,string $selected): void {
    global $id;
    $person=$plan['owners'][$selected]??null;
    echo '<section class="dbt-card"><h2>Siswa dan rekening</h2><form method="get" class="lf-search"><input type="hidden" name="id" value="'.loe($id).'"><input type="hidden" name="section" value="people"><label>Cari nama / nomor sumber<input name="q" value="'.loe($_GET['q']??'').'"></label><button class="dbt-button">Cari</button></form><div class="dbt-table-scroll"><table class="dbt-table"><thead><tr><th>Nama</th><th>Kelompok</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>';
    $q=mb_strtolower(trim((string)($_GET['q']??'')));$matches=array_filter($plan['owners'],fn($o)=>$q===''||str_contains(mb_strtolower($o['name'].' '.$o['identity']),$q));$page=max(1,(int)($_GET['page']??1));foreach(array_slice($matches,($page-1)*25,25,true) as $o)echo '<tr><td>'.loe($o['name']).'<br><small>'.loe($o['identity']).'</small></td><td>'.loe($o['source_class']).'</td><td>'.($o['ready']?'Siap':'Perlu diperiksa').'</td><td><a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'people','q'=>$q,'person'=>$o['identity'],'page'=>$page])).'#person-review">Tinjau</a></td></tr>';
    echo '</tbody></table></div><p>'.count($matches).' identitas ditemukan</p><nav class="legacy-actions">';foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $d=>$label){$p=$page+$d;if($p>0&&($p-1)*25<count($matches))echo '<a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'people','q'=>$q,'page'=>$p])).'">'.$label.'</a>';}echo '</nav></section>';
    if(!$person)return;$decision=$cfg['students'][$selected]??[];
    echo '<section class="dbt-card" id="person-review"><h2>'.loe($person['name']).'</h2><p>Identitas sumber '.loe($person['identity']).' · '.loe($person['source_class']).' · Tahun masuk '.loe($person['entry_year']??'Tidak tercatat').'</p><dl class="legacy-balance"><div><dt>SPP sumber</dt><dd>'.loe(legacy_ui_money($person['spp'])).'</dd></div><div><dt>Komite / POMG</dt><dd>'.loe(legacy_ui_money($person['komite'])).'</dd></div></dl><form method="post" class="lf-form">';lop_form_hidden('person');echo '<input type="hidden" name="identity" value="'.loe($selected).'"><label>Nama tujuan<input name="person[name]" maxlength="255" required value="'.loe($decision['name']??$person['name']).'"></label><label>Nomor induk tujuan (khusus siswa)<input name="person[nis]" maxlength="10" value="'.loe($decision['nis']??$person['nis']).'"></label><p>Identitas sumber dan ejaan asli tetap tersimpan. Nomor induk boleh sama antarunit; dalam unit harus unik.</p><button class="dbt-button dbt-button-primary">Simpan Identitas</button></form></section>';
    echo '<section class="dbt-card"><h2>Kewajiban yang dapat dibuktikan</h2><p>Pokok adalah kewajiban periode tersebut, bukan tarif terbaru. Pokok harus sama dengan pembayaran terkait ditambah sisa. Kolom kosong tidak berarti lunas.</p><form method="post" class="lf-form">';lop_form_hidden('coverage');echo '<input type="hidden" name="identity" value="'.loe($selected).'">';
    $monthlyNotes=array_values(array_filter($plan['pending'],static fn($p)=>$p['identity']===$selected&&$p['code']==='monthly_evidence'));
    if($monthlyNotes){echo '<p class="legacy-note">Lengkapi bukti periode berikut melalui peninjauan kewajiban.</p><ul>';foreach(array_slice($monthlyNotes,0,24) as $note){$proof=$note['payload']??[];echo '<li>'.loe(($proof['category']??'').' '.($proof['period']??'').' ? '.$note['message']).'</li>';}echo '</ul>';}
    $coverages=$decision['coverage']??[];$coverages[]=['category'=>'spp','period'=>'','disposition'=>'','principal'=>'','amount'=>'','evidence'=>''];foreach($coverages as $n=>$c){echo '<fieldset class="lop-fieldset"><legend>Kewajiban '.($n+1).'</legend><div class="lful-grid"><label>Komponen<select name="coverage['.$n.'][category]">';foreach(['spp'=>'SPP','komite'=>'Komite','daftar_ulang'=>'Daftar Ulang','psb'=>'PSB'] as $key=>$label)echo '<option value="'.$key.'"'.(($c['category']??'')===$key?' selected':'').'>'.$label.'</option>';echo '</select></label><label>Periode (YYYY-MM atau YYYY/YYYY)<input name="coverage['.$n.'][period]" value="'.loe($c['period']??'').'"></label><label>Status<select name="coverage['.$n.'][disposition]">';foreach([''=>'Belum diperiksa','legacy_debt'=>'Masih ada tunggakan','settled'=>'Lunas pada periode ini','not_applicable'=>'Tidak menjadi kewajiban'] as $key=>$label)echo '<option value="'.$key.'"'.(($c['disposition']??'')===$key?' selected':'').'>'.$label.'</option>';echo '</select></label><label>Pokok yang sah (Rp)<input name="coverage['.$n.'][principal]" inputmode="decimal" value="'.loe($c['principal']??'').'"></label><label>Sisa tunggakan (Rp)<input name="coverage['.$n.'][amount]" inputmode="decimal" value="'.loe($c['amount']??'0').'"></label></div><label>Bukti kewajiban<textarea name="coverage['.$n.'][evidence]" maxlength="1000">'.loe($c['evidence']??'').'</textarea></label></fieldset>';}
    echo '<label class="lop-check"><input type="checkbox" name="attest" value="1" required> Saya mengesahkan rincian kewajiban yang terisi.</label><button class="dbt-button dbt-button-primary">Simpan Peninjauan Kewajiban</button></form></section>';
}
function lop_review_savings_directory(array $plan): void {
    global $id;$q=trim((string)($_GET['bank_q']??''));$rows=array_values(array_filter($plan['owners'],fn($o)=>(($o['bank_summary']['accounts']??0)>0||!empty($o['savings']))&&($q===''||mb_stripos($o['name'].' '.$o['identity'],$q)!==false)));$pages=max(1,(int)ceil(count($rows)/25));$page=max(1,min($pages,(int)($_GET['bank_page']??1)));
    echo '<section class="dbt-card"><h2>Tabungan utama</h2><p>Saldo cocok langsung siap setelah pemilik disetujui. Gunakan Jumlah Sebenarnya hanya untuk saldo yang perlu dikoreksi.</p><form method="get" class="lf-search"><input type="hidden" name="id" value="'.loe($id).'"><input type="hidden" name="section" value="savings"><label>Cari nama / nomor sumber<input name="bank_q" value="'.loe($q).'"></label><button class="dbt-button">Cari Rekening</button></form><div class="dbt-table-scroll"><table class="dbt-table lop-bank-table"><thead><tr><th>Pemilik</th><th>Saldo sumber</th><th>Hasil jurnal</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>';
    foreach(array_slice($rows,($page-1)*25,25) as $o){$b=$o['bank_summary']??[];$ready=$o['ready']&&(!empty($o['savings'])||($b['status']??'')==='Cocok');echo '<tr><td data-label="Pemilik">'.loe($o['name']).'<br><small>'.loe($o['identity']).'</small></td><td data-label="Saldo sumber">'.loe(legacy_ui_money($b['source_balance']??null)).'</td><td data-label="Hasil jurnal">'.loe(legacy_ui_money($b['journal_balance']??null)).'</td><td data-label="Status">'.($ready?'Siap':'Perlu saldo / identitas').'</td><td><a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'savings','person'=>$o['identity'],'bank_q'=>$q,'bank_page'=>$page])).'#primary-bank">'.($ready?'Lihat Rekening':'Jumlah Sebenarnya').'</a></td></tr>';}
    echo '</tbody></table></div><p>'.count($rows).' rekening · halaman '.$page.' dari '.$pages.'</p><nav class="legacy-actions">';foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $direction=>$label){$next=$page+$direction;if($next>0&&$next<=$pages)echo '<a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'savings','bank_q'=>$q,'bank_page'=>$next])).'">'.$label.'</a>';}echo '</nav></section>';
}
function lop_review_savings(array $records,array $plan,array $cfg,string $selected): void {
    lop_review_savings_directory($plan);
    global $id;$o=$plan['owners'][$selected]??null;if(!$o)return;echo '<section class="dbt-card" id="primary-bank"><h2>Peninjauan tabungan</h2><p>Isi jumlah sebenarnya hanya jika saldo perlu dikoreksi. Sumber asli dipertahankan.</p>';
    echo '<h3>'.loe($o['name']).' · '.loe($selected).'</h3>';$derived=[];$operative=lop_promote_accounts($records,$GLOBALS['catalog']['manifest']['source_date']??null,$derived);$rows=array_values(array_filter($operative,fn($r)=>lful_identity(legacy_source_identity($r['raw']))===$selected&&in_array($r['table'],['tabungan','transaksi_m','transaksi_k'],true)));$rec=lf_reconcile($rows);$delta=$rec['balance']===null?null:lf_money(lf_cents($rec['balance'])-lf_cents($rec['incoming'])+lf_cents($rec['outgoing']));
    echo '<dl class="legacy-balance"><div><dt>Saldo sumber</dt><dd>'.loe($rec['balance']===null&&$rec['source_balance_raw']!==null?'Presisi sumber Legacy':legacy_ui_money($rec['balance'])).'</dd></div><div><dt>Hasil jurnal</dt><dd>'.loe($rec['journal_issues']?'Belum dapat dihitung lengkap':legacy_ui_money(lf_money(lf_cents($rec['incoming'])-lf_cents($rec['outgoing'])))).'</dd></div><div><dt>Selisih</dt><dd>'.loe(legacy_ui_money($delta)).'</dd></div></dl>';
    if($rec['balance']===null&&$rec['source_balance_raw']!==null)echo '<p class="dbt-info">Saldo sumber mentah: <strong>'.loe($rec['source_balance_raw']).'</strong>. Presisi sumber perlu disahkan; rekening ini tetap teridentifikasi.</p>';
    try{$effective=lf_reconcile(lop_effective_bank_rows($rows,$cfg));if($effective['incoming']!==$rec['incoming']||$effective['outgoing']!==$rec['outgoing'])echo '<p class="dbt-info">Hasil jurnal setelah koreksi draf: '.loe(legacy_ui_money(lf_money(lf_cents($effective['incoming'])-lf_cents($effective['outgoing'])))).'. Nominal ini digunakan untuk menghitung penyesuaian FIX.</p>';}catch(DomainException $e){$effective=$rec;echo '<p class="dbt-warning">'.loe($e->getMessage()).'</p>';}
    if(!empty($o['savings']))echo '<p class="dbt-info">Tabungan siap setelah pemilik disetujui. Tidak perlu mengisi ulang nominal.</p>';
    $savedFix=$cfg['op_savings'][$selected]??$o['balance_fix']??[];if(!empty($savedFix['confirmed']))echo '<dl class="legacy-balance"><div><dt>Saldo yang Disahkan / FIX</dt><dd>'.loe(legacy_ui_money($savedFix['amount'])).'</dd></div><div><dt>Penyesuaian terhadap jurnal</dt><dd>'.loe(legacy_ui_money(lf_money(lf_cents($savedFix['amount'])-lf_cents($effective['incoming'])+lf_cents($effective['outgoing'])))).'</dd></div></dl>';
    if(empty($o['savings']))foreach($rec['issues'] as $issue)echo '<p class="dbt-warning">'.loe($issue).'</p>';else echo '<p class="dbt-info">Siap sesuai pemeriksaan sistem. Saldo akhir: '.loe(legacy_ui_money($o['savings']['balance'])).'. Catatan sumber dan penyesuaian tersimpan untuk audit.</p>';echo '<p><a class="dbt-button" href="?id='.loe($id).'&amp;section=people&amp;person='.urlencode($selected).'#person-review">Identitas dan kewajiban pemilik</a></p>';
    $applied=lf_one($GLOBALS['koneksi'],'SELECT a.id,o.id owner_id FROM legacy_op_accounts a JOIN legacy_op_owners o ON o.id=a.owner_id AND o.unit_id=a.unit_id WHERE o.batch_id=? AND o.source_identity=?',[$id,$selected]);
    if($applied)echo '<p class="dbt-info">Rekening ini sudah digunakan. Koreksi dilakukan melalui rekening agar transaksi lanjutan ikut diperiksa.</p><a class="dbt-button" href="legacy_accounts.php?'.loe(http_build_query(['batch'=>$id,'owner'=>$applied['owner_id']])).'">Buka Rekening &amp; Koreksi</a>';
    if(!$applied){
    $fix=$cfg['op_savings'][$selected]??$o['balance_fix']??[];$pending=$_SESSION['lop_balance_confirmation'][$id][$selected]??null;if($pending&&$pending['version']===(int)$GLOBALS['draft']['version'])$fix=$pending['fix'];if(($_POST['action']??'')==='savings')$fix=['amount'=>is_string($_POST['amount']??null)?$_POST['amount']:'','evidence'=>is_string($_POST['evidence']??null)?$_POST['evidence']:'','confirmed'=>($_POST['attest']??'')==='1'];echo '<div class="lop-fix"><h3>Jumlah Sebenarnya</h3><p>Isi saldo yang disahkan yayasan. Selisih akan dicatat sebagai penyesuaian migrasi, tanpa menambah kas masuk.</p><form method="post" class="lf-form">';lop_form_hidden('savings');echo '<input type="hidden" name="identity" value="'.loe($selected).'"><label>Jumlah Sebenarnya / Saldo FIX (Rp)<input name="amount" inputmode="decimal" required value="'.loe($fix['amount']??$rec['balance']).'"></label><label>Bukti / alasan<textarea name="evidence" minlength="10" maxlength="1000" required>'.loe($fix['evidence']??'').'</textarea></label><label class="lop-check"><input type="checkbox" name="attest" value="1" required'.(!empty($fix['confirmed'])?' checked':'').'> Saya mengesahkan nominal dan bukti saldo peralihan ini.</label><button class="dbt-button dbt-button-primary">Periksa Saldo FIX</button></form></div>';
    }
    echo '<h3>Jurnal sumber</h3><p>Gunakan koreksi persiapan hanya untuk baris yang terbukti keliru. Setelah penerapan, gunakan Koreksi pada rekening agar saldo berjalan dihitung ulang.</p>';
    $page=max(1,(int)($_GET['page']??1));$journals=array_values(array_filter($rows,fn($r)=>$r['table']!=='tabungan'));foreach(array_slice($journals,($page-1)*20,20) as $r){$raw=$r['raw'];$fix=$cfg['op_journals'][$r['row_key']]??[];echo '<details><summary>'.loe($raw['TANGGAL']??'Tanggal tidak tercatat').' · Masuk '.loe(legacy_ui_money($raw['MASUK']??0)).' · Keluar '.loe(legacy_ui_money($raw['KELUAR']??0)).'</summary><form method="post" class="lf-form">';lop_form_hidden('journal');echo '<fieldset '.($applied?'disabled':'').'><input type="hidden" name="row_key" value="'.loe($r['row_key']).'"><input type="hidden" name="identity" value="'.loe($selected).'"><label>Tanggal WIB<input type="datetime-local" name="date" required value="'.loe(str_replace(' ','T',$fix['date']??$raw['TANGGAL']??'')).'"></label><div class="lful-grid"><label>Masuk (Rp)<input name="incoming" required value="'.loe($fix['incoming']??$raw['MASUK']??0).'"></label><label>Keluar (Rp)<input name="outgoing" required value="'.loe($fix['outgoing']??$raw['KELUAR']??0).'"></label></div><label>Bukti / alasan<textarea name="evidence" minlength="10" maxlength="1000" required>'.loe($fix['evidence']??'').'</textarea></label><label class="lop-check"><input type="checkbox" name="attest" value="1" required> Saya mengesahkan koreksi jurnal ini.</label><button class="dbt-button dbt-button-primary">Simpan Koreksi Persiapan</button></fieldset></form></details>';}
    echo '<nav class="legacy-actions">';foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $d=>$label){$p=$page+$d;if($p>0&&($p-1)*20<count($journals))echo '<a class="dbt-button" href="?'.loe(http_build_query(['id'=>$id,'section'=>'savings','person'=>$selected,'page'=>$p])).'">'.$label.'</a>';}echo '</nav></section>';
}
